def greedy_change(coins, amount):
    chosen = []
    for coin in sorted(coins, reverse=True):
        while amount >= coin:
            chosen.append(coin)
            amount -= coin
    return chosen if amount == 0 else None

print(greedy_change([1, 3, 4], 6))
print(greedy_change([3, 4], 6))

def minimum_coins_plain(coins, amount):
    def solve(remaining):
        if remaining == 0:
            return 0
        best = None
        for coin in coins:
            if coin <= remaining:
                rest = solve(remaining - coin)
                if rest is not None:
                    candidate = rest + 1
                    if best is None or candidate < best:
                        best = candidate
        return best
    return solve(amount)

print(minimum_coins_plain([1, 3, 4], 6))
print(minimum_coins_plain([3, 4], 6))
print(minimum_coins_plain([4], 6))

def brute_min_coins(coins, amount):
    if amount == 0:
        return 0
    best = None
    for coin in coins:
        if coin <= amount:
            previous = brute_min_coins(coins, amount - coin)
            if previous is not None:
                candidate = previous + 1
                if best is None or candidate < best:
                    best = candidate
    return best

print(brute_min_coins([1, 3, 4], 6))
print(brute_min_coins([2, 5], 3))
print(brute_min_coins([], 0))

